Boolean dei_sc_icon_programming_enter( void )
{                
  dei_sc_set_mode( DEI_SC_MODE_PROGRAMMING ) ; 
  dei_sc_ngrf_mode = DEI_SC_NGRF_MODE_PROGRAMMING_ENTER;	
  dei_sc_tx(DEI_SC_ACK_MODE_CONFIGURATION,DEI_SC_NORMAL_TX,1000);
    
  return TRUE;
}

